import{_ as o,o as a,c as i,a2 as n}from"./chunks/framework.CnJ-JtFX.js";const p=JSON.parse('{"title":"EP.20 从 Schema 到可运行系统","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.20-mini-lowcode-codegen.md","filePath":"comics/EP.20-mini-lowcode-codegen.md","lastUpdated":1792683644000}'),t={name:"comics/EP.20-mini-lowcode-codegen.md"};function l(c,e,s,d,r,m){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="ep-20-从-schema-到可运行系统" tabindex="-1">EP.20 从 Schema 到可运行系统 <a class="header-anchor" href="#ep-20-从-schema-到可运行系统" aria-label="Permalink to &quot;EP.20 从 Schema 到可运行系统&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/20-mini-lowcode-codegen">guide/20-mini-lowcode-codegen</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>一份 Schema JSON</strong>：像素酱展示设计器产出的一份 Schema JSON，包含 page、text 等节点。</li><li><strong>两个产物</strong>：Codegen 把 Schema 转换成两个产物——可运行的 <code>.vue</code> 文件（Vue 组件）和 <code>.json</code> 文件（Schema 原文）。</li><li><strong>丢进去就能跑</strong>：标签君把产物丢到任意 Vue 项目里，不需要修改业务代码，直接 <code>pnpm dev</code> 就能跑起来。</li><li><strong>进阶卷完成</strong>：码叔结案——进阶卷完成，你已理解低代码引擎全链路（Schema → Renderer → Designer → History → Plugin → Codegen），再用 amis / lowcode-engine 已看穿黑盒。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-schema-是中间产物" tabindex="-1">第一格：Schema 是中间产物 <a class="header-anchor" href="#第一格-schema-是中间产物" aria-label="Permalink to &quot;第一格：Schema 是中间产物&quot;">​</a></h3><p>Schema 是设计器的产出，但 Schema 本身不能直接在浏览器里跑。要变成可运行的系统，需要 Codegen（出码）把 Schema 转换成目标技术栈的代码。</p><p>Schema 的价值在于<strong>中间表示</strong>——它不绑定具体框架，同一份 Schema 可以出 Vue 代码、React 代码、甚至小程序代码。</p><h3 id="第二格-两个产物" tabindex="-1">第二格：两个产物 <a class="header-anchor" href="#第二格-两个产物" aria-label="Permalink to &quot;第二格：两个产物&quot;">​</a></h3><p>mini-lowcode 的 Codegen 产出两个文件：</p><ol><li><strong><code>.vue</code> 文件</strong>：可运行的 Vue 单文件组件，template 部分由 Schema 转换而来。这个文件可以直接丢到任意 Vue 项目里运行。</li><li><strong><code>.json</code> 文件</strong>：Schema 原文，供其他工具消费（如服务端渲染、二次编辑、跨端渲染）。</li></ol><p><code>.vue</code> 是面向「运行」的产物，<code>.json</code> 是面向「数据」的产物。两者配合，既保证可运行，又保留可编辑性。</p><h3 id="第三格-为什么丢进去就能跑" tabindex="-1">第三格：为什么丢进去就能跑 <a class="header-anchor" href="#第三格-为什么丢进去就能跑" aria-label="Permalink to &quot;第三格：为什么丢进去就能跑&quot;">​</a></h3><p>因为 Codegen 生成的 <code>.vue</code> 文件是<strong>标准 Vue 单文件组件</strong>，不依赖 mini-lowcode 的运行时。它只依赖 Vue 本身和基础组件库（如 text-comp、button-comp）。</p><p>这意味着：</p><ul><li>生成的代码没有黑盒运行时，可读、可调试、可二次修改；</li><li>不需要在业务项目里引入 mini-lowcode 引擎；</li><li>生成的代码性能和手写 Vue 一致。</li></ul><p>对比「运行时渲染」方案（如 lowcode-engine 的出码），Codegen 生成的是静态代码，没有运行时开销。</p><h3 id="第四格-全链路打通" tabindex="-1">第四格：全链路打通 <a class="header-anchor" href="#第四格-全链路打通" aria-label="Permalink to &quot;第四格：全链路打通&quot;">​</a></h3><p>进阶卷六章（EP.15 是过渡，EP.16-20 是核心）从零搭建了完整的低代码引擎：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Schema（数据）→ Renderer（渲染）→ Designer（拖拽）→ History（撤销）→ Plugin（扩展）→ Codegen（出码）</span></span></code></pre></div><p>每一层都亲手实现过，理解了每一层解决什么问题、有什么坑。再回头用 amis / Formily / lowcode-engine，就能看穿黑盒——知道它内部大概是怎么实现的，遇到问题能精准定位。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>出码产物依赖运行时</strong>：如果生成的代码依赖 mini-lowcode 的运行时组件，业务项目就要引入引擎，失去出码的意义。出码产物应该只依赖标准框架。</li><li><strong>表达式出码要转译</strong>：Schema 里的 <code>$&amp;#123;&amp;#123; name &amp;#125;&amp;#125;</code> 表达式在出码时要转译成 Vue 的 <code>&amp;#123;&amp;#123; name &amp;#125;&amp;#125;</code> 模板语法，不能原样输出。</li><li><strong>事件出码要生成 handler</strong>：Schema 里的 <code>onClick</code> 事件在出码时要生成对应的方法，不能直接输出字符串。</li><li><strong>样式出码要处理</strong>：Schema 里的 style 要转成 Vue 的 <code>:style</code> 绑定，class 要转成 <code>:class</code>。</li><li><strong>出码产物要可读</strong>：生成的代码要格式化、有缩进、有注释，否则用户拿到手不敢改。</li><li><strong>不要在出码阶段做太多转换</strong>：出码是 Schema → 代码的直译，不要在出码阶段做复杂的逻辑转换，复杂逻辑应该在 Schema 设计阶段就定好。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. Codegen 为什么要产出 .vue 和 .json 两个文件，而不是只产出一个？</b></summary><p>两个文件面向不同用途：</p><ol><li><strong><code>.vue</code> 文件</strong>：面向「运行」。是标准 Vue 单文件组件，可以直接丢到任意 Vue 项目里运行，不依赖 mini-lowcode 引擎。</li><li><strong><code>.json</code> 文件</strong>：面向「数据」。是 Schema 原文，供其他工具消费——比如服务端渲染、二次编辑、跨端渲染（同一份 Schema 出 React 或小程序代码）。</li></ol><p>只产出 <code>.vue</code> 会丢失可编辑性（用户改了 .vue 就无法反向同步回 Schema）；只产出 <code>.json</code> 则无法直接运行。两个文件配合，既保证可运行，又保留可编辑性。</p></details><details><summary><b>2. 为什么出码产物不依赖 mini-lowcode 的运行时？</b></summary><p>因为出码的目的是<strong>让业务项目能独立运行</strong>。如果生成的代码依赖 mini-lowcode 的运行时组件（如 Renderer、表达式求值器），业务项目就要引入整个 mini-lowcode 引擎，这违背了出码的初衷——出码就是为了摆脱引擎依赖。</p><p>出码产物应该只依赖：</p><ul><li>标准框架（Vue / React）；</li><li>基础组件库（text-comp、button-comp 等简单组件）。</li></ul><p>这样生成的代码可读、可调试、可二次修改，性能和手写代码一致。用户拿到产物后，mini-lowcode 引擎就可以「功成身退」了。</p></details><details><summary><b>3. 进阶卷全链路指的是什么？走完一遍有什么价值？</b></summary><p>全链路指的是低代码引擎的六大模块：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Schema（数据定义）→ Renderer（递归渲染）→ Designer（拖拽编辑）→ History（撤销重做）→ Plugin（扩展）→ Codegen（出码）</span></span></code></pre></div><p>走完一遍的价值：</p><ol><li><strong>看穿黑盒</strong>：再用 amis / lowcode-engine 时，知道每个功能背后的实现原理，遇到问题能精准定位是哪一层的问题；</li><li><strong>精准选型</strong>：理解每个模块的职责和边界，能根据需求判断该用哪个产品、该怎么组合；</li><li><strong>二次开发</strong>：需要扩展现成框架时，知道从哪里切入、怎么写插件。</li></ol><p>核心不是造轮子，而是<strong>理解轮子</strong>——理解了原理，工具才是工具，而不是黑盒魔法。</p></details>',27)])])}const g=o(t,[["render",l]]);export{p as __pageData,g as default};
